        heapq.heappush(heap, (nf, ng, nr, nc, path + action))

lab1_06_admissible.py.prelude:
from collections import deque

def bfs_from_goal(graph, goal):
    """True (unweighted) distance from every node to the goal."""
    dist = {goal: 0}
    queue = deque([goal])
    while queue:
        u = queue.popleft()
        for v in graph[u]:
            if v not in dist:
                dist[v] = dist[u] + 1
                queue.append(v)
    return dist

lab1_06_admissible.py.solution:
def inadmissible_nodes(graph, heuristics, goal):
    true_dist = bfs_from_goal(graph, goal)
    bad = []
    for node in graph:
        actual = true_dist.get(node, float('inf'))
        if heuristics[node] > actual:
            bad.append(node)
    return sorted(bad)

