def mutation(chromosome, rate):
    """Each bit has a `rate` chance of being flipped (0 -> 1, 1 -> 0)."""
    new_chromosome = ""
    for bit in chromosome:
        if random.random() < rate:
            new_chromosome += "1" if bit == "0" else "0"
        else:
            new_chromosome += bit
    return new_chromosome

