lab2_09_schedule_fitness.py.solution:
def fitness(chromosome, N, T):
    """overlap penalty: for each timeslot, (#courses scheduled - 1) if more than one is scheduled.
    consistency penalty: for each course, 1 if it is not scheduled exactly once.
    Return -(overlap + consistency)."""
    overlap = 0
    for t in range(T):
        segment = chromosome[t * N:(t + 1) * N]
        scheduled = segment.count("1")
        if scheduled > 1:
            overlap += scheduled - 1
    consistency = 0
    for i in range(N):
        times = sum(1 for t in range(T) if chromosome[t * N + i] == "1")
        if times != 1:
            consistency += 1
    return -(overlap + consistency)

lab3_01_minimax.py.solution:
def minimax(depth, index, is_max, leaves):
    """Value of the node at (depth levels above the leaves, index among its level).
    depth == 0 means the node is leaves[index]."""
    if depth == 0:
        return leaves[index]
    left = minimax(depth - 1, 2 * index, not is_max, leaves)
    right = minimax(depth - 1, 2 * index + 1, not is_max, leaves)
    if is_max:
        return max(left, right)
    else:
        return min(left, right)

