lab3_03_ab_full.py.solution:
def alpha_beta(depth, index, is_max, leaves, alpha, beta):
    """Return (value, pruned) where pruned counts every child branch that was skipped."""
    if depth == 0:
        return leaves[index], 0
    pruned = 0
    if is_max:
        best = -math.inf
        for i in range(2):
            value, p = alpha_beta(depth - 1, 2 * index + i, False, leaves, alpha, beta)
            pruned += p
            best = max(best, value)
            alpha = max(alpha, best)
            if beta <= alpha:
                pruned += 2 - i - 1
                break
    else:
        best = math.inf
        for i in range(2):
            value, p = alpha_beta(depth - 1, 2 * index + i, True, leaves, alpha, beta)
            pruned += p
            best = min(best, value)
            beta = min(beta, best)
            if beta <= alpha:
                pruned += 2 - i - 1
                break
    return best, pruned

